from urllib.parse import urlparse

def real_domain(url):
    host = urlparse(url).hostname or ""
    return ".".join(host.split(".")[-2:])

def blocked(attempts, limit):
    streak, out = {}, set()
    for user, ok in attempts:
        streak[user] = 0 if ok else streak.get(user, 0) + 1
        if streak[user] > limit:
            out.add(user)
    return sorted(out)
